  'plans.faqWhatIsPlusAnswer': 'Chatyy\'nin tüm konuşmalarını, fotoğraflarını ve videolarını koruyan premium planıdır. {plan} ile istemeden bir şey silsen bile, 30 gün içinde geri alabilirsin. Ayrıca, 200GB depolama alanı, kişisel asistan olarak One AI ve 100MB\'a kadar dosya gönderme imkanı sunar.',
