  "waImport.agendaAskBody": "WhatsApp göndereni rehberinizdeki adla kaydetti. Doğru hesabı numarayla bulmak için Chatyy bu adı kişilerinizde arar ve chatyy.com.br'ye numaraların yalnızca bir kodunu (SHA-256 özeti) gönderir — asla numaranın kendisini değil, ve hiçbir şey saklanmaz. Bu olmadan arama yalnızca adla yapılır.",
